import{_ as o,o as t,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const n="/images/logic-studio/user-guide/blocks-a-fr.png",m=JSON.parse('{"title":"Blocks A","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/logic-studio/user-guide/blocks-a.md","filePath":"fr/projects/logic-studio/user-guide/blocks-a.md","lastUpdated":1795627958000}'),i={name:"fr/projects/logic-studio/user-guide/blocks-a.md"};function s(l,e,c,u,d,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="blocks-a" tabindex="-1">Blocks A <a class="header-anchor" href="#blocks-a" aria-label="Permalink to &quot;Blocks A&quot;">​</a></h1><h2 id="premier-exemple" tabindex="-1">Premier exemple <a class="header-anchor" href="#premier-exemple" aria-label="Permalink to &quot;Premier exemple&quot;">​</a></h2><p>L’automatisation allume la lumière du couloir lorsque le capteur de mouvement passe à <code>on</code>.</p><ol><li>Choisis <strong>Nouveau projet → Blocks A</strong> et donne un nom au projet. Le bloc <strong>Automatisation</strong> apparaît sur le canevas.</li><li>Ouvre <strong>Déclencheurs</strong> et glisse un déclencheur d’état dans <strong>Quand</strong>. La capture utilise <code>binary_sensor.flur_bewegung</code> et l’état <code>on</code>. Choisis ton propre capteur ou une entrée de test.</li><li>Ouvre <strong>Actions</strong> et place une action dans <strong>Alors</strong>. La capture utilise <code>light.flur</code> et <strong>allumer</strong>. Tu peux choisir une deuxième entrée de test comme cible. Laisse <strong>Seulement si</strong> vide pour cet exemple.</li><li>Clique sur le drapeau pour vérifier les blocs. Si la vérification réussit, choisis <strong>Ouvrir en YAML HA</strong> et contrôle <code>triggers</code> et <code>actions</code> avant d’exporter.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-a-fr.png"><img src="'+n+'" alt="Blocks A avec un déclencheur dans Quand et une action dans Alors"></a></p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><h3 id="palette-et-connexions" tabindex="-1">Palette et connexions <a class="header-anchor" href="#palette-et-connexions" aria-label="Permalink to &quot;Palette et connexions&quot;">​</a></h3><p>Choisis un bloc selon son rôle. La forme des connexions indique où placer une valeur ou une action.</p><h3 id="declencheurs-et-conditions" tabindex="-1">Déclencheurs et conditions <a class="header-anchor" href="#declencheurs-et-conditions" aria-label="Permalink to &quot;Déclencheurs et conditions&quot;">​</a></h3><p>Un déclencheur démarre l’automatisation. Une condition peut vérifier si l’autre entrée est désactivée.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><p>Empile les actions dans leur ordre d’exécution.</p><h3 id="selecteurs-ha" tabindex="-1">Sélecteurs HA <a class="header-anchor" href="#selecteurs-ha" aria-label="Permalink to &quot;Sélecteurs HA&quot;">​</a></h3><p>Choisis une entité, une action, un appareil, une zone, une étiquette ou un étage. Vérifie l’identifiant correspondant dans le YAML.</p><h3 id="brouillon-ha-yaml" tabindex="-1">Brouillon HA-YAML <a class="header-anchor" href="#brouillon-ha-yaml" aria-label="Permalink to &quot;Brouillon HA-YAML&quot;">​</a></h3><p>Ouvre l’automatisation générée en brouillon. Le nom de son projet source y est affiché.</p><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p>Vérifie le YAML et utilise-le dans HA. Teste le déclencheur et consulte la trace de l’automatisation.</p><h2 id="en-cas-de-probleme" tabindex="-1">En cas de problème <a class="header-anchor" href="#en-cas-de-probleme" aria-label="Permalink to &quot;En cas de problème&quot;">​</a></h2><p>Si une liste est vide, vérifie que le système HA connecté contient les éléments recherchés.</p>',20)])])}const g=o(i,[["render",s]]);export{m as __pageData,g as default};
